using System;using System.Collections.Generic;using System.Drawing;using System.Linq;using System.Reflection;using System.Windows.Forms;using ScreenDock;
class LayoutTests{
 static void Check(bool x,string m){if(!x)throw new Exception(m);}static void Reject(Action a){bool failed=false;try{a();}catch(Exception){failed=true;}Check(failed,"invalid layout accepted");}
 [STAThread]static void Main(){var a=new Display{Identity="a",Device="a",Name="Display A",Active=true,Primary=true,Number=1,Mode=new Native.Mode{x=100,y=200,width=1920,height=1080,bits=32,frequency=60}};var b=new Display{Identity="b",Device="b",Name="Display B",Active=true,Number=2,Mode=new Native.Mode{x=2020,y=200,width=2560,height=1440,bits=32,frequency=144}};var list=new List<Display>{a,b};var plan=DisplayLayout.Plan(list);Check(plan["a"].x==0&&plan["b"].x==1920&&plan["b"].y==0,"normalize primary");var copy=DisplayLayout.Copy(list);var m=copy[1].Mode;m.x=110;copy[1].Mode=m;Check(b.Mode.x==2020,"preview isolation");Reject(()=>DisplayLayout.Plan(copy));m.x=9000;copy[1].Mode=m;Reject(()=>DisplayLayout.Plan(copy));DisplayLayout.Snap(copy[1],copy);DisplayLayout.Plan(copy);m=copy[1].Mode;m.x=100;m.y=-1300;copy[1].Mode=m;DisplayLayout.Snap(copy[1],copy);plan=DisplayLayout.Plan(copy);Check(plan["b"].y==-1440,"above primary placement");
 Application.EnableVisualStyles();using(var editor=new LayoutEditor(list,true)){editor.Show();Application.DoEvents();var map=editor.Controls.OfType<Map>().Single();var parent=editor.Controls.OfType<FlowLayoutPanel>().Single();Check(parent.Controls.Cast<Control>().All(c=>c.Bottom<=parent.ClientSize.Height),"wrapped dropdown");using(var bitmap=new Bitmap(editor.Width,editor.Height)){editor.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));}var hit=(Dictionary<Rectangle,Display>)typeof(Map).GetField("hit",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(map);var target=hit.Single(x=>x.Value.Number==2);var center=new Point(target.Key.X+target.Key.Width/2,target.Key.Y+target.Key.Height/2);bool changed=false;map.Changed=()=>changed=true;Action<string,Point> mouse=(name,pt)=>typeof(Map).GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(map,new object[]{new MouseEventArgs(MouseButtons.Left,1,pt.X,pt.Y,0)});mouse("OnMouseDown",center);var end=new Point(center.X,center.Y-260);mouse("OnMouseMove",end);mouse("OnMouseUp",end);Check(changed&&!map.Capture,"drag commit");DisplayLayout.Plan(map.Displays);editor.ClientSize=new Size(1200,800);Application.DoEvents();Check(map.Width>880&&map.Height>345,"editor resize");}
 Console.WriteLine("PASS: primary normalization, preview isolation, overlap/gap rejection, snapping above and beside, dropdown bounds, editor resize. No hardware changes.");}
}
